def pre(n):
    return 0 <= n <= 300

def count_sevens_in(i):
    c = 0
    x = i
    while x > 0:
        if x % 10 == 7:
            c += 1
        x = x // 10
    return c

def post(n, result):
    total = 0
    for i in range(n):
        if i % 11 == 0 or i % 13 == 0:
            total += count_sevens_in(i)
    return result == total
